INSERT INTO `job_post` VALUES ('1971424431720968193', '5684103397994088016', '需要一名住家保姆，同城的优先考虑', null, '0', '1908512560381947906', 'A04A05A02', '月嫂', '2025-10-25 22:00:00', '2025-11-23 21:00:00', '2025-11-23 21:00:00', '女', '', '1', '南康国际家私城', null, '江西省赣州市南康区东山街道迎宾东大道与工业五路交叉口西北140米', '114.77959', '25.68582', '19979759191', null, '根据家庭日常需求设定，是完成工作的核心能力。\n家务能力：熟练完成日常保洁（打扫房间、清洁厨房卫生间）、衣物清洗与收纳（区分材质洗涤、熨烫）、家庭餐制作（根据口味和健康需求烹饪，会做家常菜是基础，部分家庭要求会辅食或特定菜系）。\n专项照顾能力（按需）：\n照顾婴幼儿：需掌握喂奶、拍嗝、辅食添加、哄睡、简单早教互动，以及基础的婴幼儿安全防护（如防磕碰、应急处理）。\n照顾老人：需协助老人穿衣、洗漱、用药提醒，陪伴散步，关注老人身体状况，部分需掌握基础的失能 / 半失能老人护理（如翻身、按摩）。\n其他：若家庭有宠物，需具备基础的宠物喂养、遛狗、清洁毛发能力。', null, '200', '元/天', null, null, null, null, '119', null, null, null, null, '4', '南康区', '360703', '赣州市', '3607', '19979759191', '2025-09-26 11:59:46', '19979759191', '2026-06-05 14:27:33', null, null, '0');
