INSERT INTO `sys_log` VALUES ('1819634460632162306', '2', '文章内容-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.job.cms.controller.CmsArticlesController.add()', null, '[{\"categoryId\":\"1819634297549234177\",\"content\":\"<p>1、满100元才能申请提现。</p>\\n<p><span style=\\\"white-space: normal;\\\">2、提现账号可填写支付宝信息，支付宝请填写支付宝账号和真实姓名。</span></p>\\n<p><span style=\\\"white-space: normal;\\\">3、提现申请提交以后两个工作日内后台会进行转账操作。</span></p>\\n<p><span style=\\\"white-space: normal;\\\">4、审核结果可以在提现记录里面查看，如果审核失败了，基本上上因为账号错误引起。</span></p>\\n<p><span style=\\\"white-space: normal;\\\">5、节假日审核时间可能会相应的延长，请耐心等待。</span></p>\\n<p>&nbsp;</p>\",\"createBy\":\"admin\",\"createTime\":1722669637233,\"id\":\"1819634460590219265\",\"sort\":1,\"status\":1,\"sysOrgCode\":\"A01\",\"title\":\"提现规则\"}]', null, '7', null, '2024-08-03 15:20:37', null, null, null);
