INSERT INTO `sys_log` VALUES ('1820731143717875714', '2', '内容类别-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.job.cms.controller.CmsCategoryController.add()', null, '[{\"code\":\"safe\",\"createBy\":\"admin\",\"createTime\":1722931106839,\"description\":\"职位安全提醒内容\",\"hasChild\":\"0\",\"id\":\"1820731143629795330\",\"name\":\"安全提示\",\"pid\":\"0\",\"sort\":1,\"status\":1,\"sysOrgCode\":\"A01\"}]', null, '21', null, '2024-08-06 15:58:27', null, null, null);
INSERT INTO `sys_log` VALUES ('1820731669423550466', '2', '文章内容-添加', '2', 'admin', '管理员', '0:0:0:0:0:0:0:1', 'org.jeecg.modules.job.cms.controller.CmsArticlesController.add()', null, '[{\"categoryId\":\"1820731143629795330\",\"content\":\"<p>&ldquo;零工招聘&rdquo;是信息发布、撮合平台，不参与招工和找活双方的交易，不对双方的交易纠纷负责。该信息由用户发布，请找活者注意甄别并保护好自己权益，如遇 代付、收费、刷单、传销、充值、押金、诱导购物购车、收培训费等违规行为，请立即向零工招聘平台投诉举报!</p>\\n<p>招工和找活双方，应自行通过微信、电话录音等书面方式明确交易信息(包括但不限于工资、工时、工期、结算方式、工作要求等)</p>\\n<p>如遇交易纠纷，请优先协商解决，或寻求当地相关部门的帮助(如:劳动纠纷可拨打12333;交易纠纷可向法院起诉;遇诈骗可向当地警方求助)</p>\\n<p>切记:对接支付宝/微信/银行卡验证码的都是骗子!</p>\\n<p>零工招聘在此郑重声明:因找活者未注意到上述风险所导致的任何损失或责任，均由找活者自行承担，零工招聘对此不承担任何责任。</p>\\n<p>如招工或找活因此给零工招聘造成其他负面影响，零工招聘保留追究其法律责任的权利。</p>\\n<p>特此声明!</p>\",\"createBy\":\"admin\",\"createTime\":1722931232195,\"id\":\"1820731669398384641\",\"sort\":1,\"status\":1,\"sysOrgCode\":\"A01\",\"title\":\"安全提醒\"}]', null, '15', null, '2024-08-06 16:00:32', null, null, null);
