INSERT INTO `sys_log` VALUES ('1860131346395987970', '2', '招工信息-编辑', '3', 'admin', '管理员', '180.102.213.13', 'org.jeecg.modules.job.job.controller.JobPostController.edit()', null, '[{\"address\":\"金华市金东区金东区\",\"addressName\":\"金东区\",\"browseNumber\":2,\"city\":\"金东区\",\"closeTime\":1732928820000,\"createTime\":1732324222000,\"descr\":\"0押金0门槛超时投诉不扣钱！\\n不拖欠工资，可预支工资！\\n金华，傅村，汤溪，义乌，温州可就近安排，\\n送餐区域集中（配送范围三公里），无需经验\\n 有师傅一对一，系统派单，公平公正，\\n待遇：工龄奖，全勤奖，冲单奖，年终奖， 积分奖，夜宵单补贴，距离补贴，高温补贴，装备免费，免健康证，公司提供车\\n 底薪+提成（5-8块）\\n新人入职福利3000-5000，入职当天安排宿舍\\n 地址：婺城区，金东区，义乌，温州可就近安排\",\"endTime\":1732928820000,\"id\":\"1860128725060845569\",\"latitude\":\"29.099822\",\"longitude\":\"119.692821\",\"name\":\"刘站长\",\"orderCount\":0,\"phone\":\"13106021372\",\"postSource\":1,\"postStatus\":\"2\",\"recruitsNumber\":10,\"salary\":\"8000-14000元/月\",\"settlementCount\":0,\"sexRequire\":\"不限\",\"startTime\":1732324020000,\"title\":\"美团站点直聘短期、长期、寒暑假工\",\"typeIds\":\"1818487668901396482\",\"typeNames\":\"外卖骑手\",\"updateBy\":\"admin\",\"updateTime\":1732324847184,\"userId\":\"e9ca23d68d884d4ebb19d07889727dae\"}]', null, '24', null, '2024-11-23 09:20:47', null, null, null);
